pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Sink sink;

    function setUp() public {
        c = new C();
        sink = new Sink();
        vm.deal(address(c), 1 ether);
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount > 0 && amount <= 1 ether);
        vm.assume(actor != address(0));

        // the transfer must go to a counterparty that only accepts exactly the
        // requested amount; the fuzzer supplies actor and amount
        vm.prank(actor); // sender does not matter beyond being non-owner-irrelevant
        vm.stopPrank();
        vm.prank(address(this)); // address(this) is the deployer, hence c's owner
        sink.setExpected(amount);

        bool ok;
        vm.prank(address(this)); // owner calls sendTo
        try c.sendTo(address(sink), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // c must be able to pay out exactly the requested amount
        assertTrue(ok);
    }
}

contract Sink {
    uint256 expected;

    function setExpected(uint256 e) external {
        expected = e;
    }

    receive() external payable {
        require(msg.value == expected);
    }
}

