pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address receiver, uint256 amount) public {
        // owner of c is this test contract; fuzz any other actor
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        // checks require amount > 0, keep the domain wide on amounts/receivers
        amount = bound(amount, 1, type(uint256).max);

        // fund c so the transfer itself can succeed when it is attempted
        vm.deal(address(c), amount);

        uint256 g0 = gasleft();
        vm.prank(actor);
        (bool ok,) = address(c).call(abi.encodeCall(C.sendTo, (receiver, amount)));
        uint256 used = g0 - gasleft();

        // Rule: a sendTo call by a non-owner always reverts AND does so at the
        // ownership require, before any transfer is attempted, so it consumes
        // well under 6000 gas. The mutant executes the transfer first (a CALL
        // with nonzero value costs >= 9000 gas) and only then reverts.
        assertTrue(!ok && used < 6000, "reverting sendTo must not perform the transfer");
    }
}

